# 코드(원하는 상태)와 실제 클라우드(현재 상태) 비교 — plan 이 하는 일의 축소판
want = {"sg-web": {"ingress": ["443/0.0.0.0/0"]},
        "s3-logs": {"public": False, "versioning": True},
        "db-main": {"multi_az": True}}
real = {"sg-web": {"ingress": ["443/0.0.0.0/0", "22/0.0.0.0/0"]},
        "s3-logs": {"public": False, "versioning": False},
        "tmp-ec2": {"type": "t3.large"}}
for k in sorted(want.keys() | real.keys()):
    if k not in real: print(f"+ 만들 것     {k}")
    elif k not in want: print(f"- 코드에 없음 {k} (손으로 만든 것?)")
    else:
        for f in sorted(want[k].keys() | real[k].keys()):
            if want[k].get(f) != real[k].get(f):
                print(f"~ 바꿀 것     {k}.{f}: {real[k].get(f)} -> {want[k].get(f)}")
# + 만들 것     db-main
# ~ 바꿀 것     s3-logs.versioning: False -> True
# ~ 바꿀 것     sg-web.ingress: ['443/0.0.0.0/0', '22/0.0.0.0/0'] -> ['443/0.0.0.0/0']
# - 코드에 없음 tmp-ec2 (손으로 만든 것?)

# IAM 정책에서 '너무 넓은 권한' 찾기 (가상 정책)
pols = {
    "app-role": [{"Effect": "Allow", "Action": ["s3:GetObject"], "Resource": "arn:aws:s3:::rides/*"}],
    "ci-role":  [{"Effect": "Allow", "Action": ["*"], "Resource": "*"}],
    "ops-role": [{"Effect": "Allow", "Action": ["ec2:*"], "Resource": "*"}],
}
for role, stmts in pols.items():
    for s in stmts:
        acts = s["Action"]
        wide = [a for a in acts if a == "*" or a.endswith(":*")]
        if s["Effect"] == "Allow" and (wide or s["Resource"] == "*"):
            print(f"{role}: Action={acts} Resource={s['Resource']} -> 좁힐 것")
        else:
            print(f"{role}: 통과")
# app-role: 통과
# ci-role: Action=['*'] Resource=* -> 좁힐 것
# ops-role: Action=['ec2:*'] Resource=* -> 좁힐 것
